export function FullTicketForm({onCreate}:{onCreate:(values:TicketDraft)=>void}){const [form,setForm]=useState<Values>(emptyValues);const id=useId();return <form onSubmit={event=>{event.preventDefault();if(!form.title.trim()||!validEstimate(form.estimateHours))return;onCreate(toDraft(form));setForm(emptyValues());}}><label htmlFor={`${id}-title`}>Tytuł</label><input id={`${id}-title`} name="title" value={form.title} required onChange={event=>{const value=event.currentTarget.value;setForm(previous=>updateValue(previous,"title",value));}}/><label htmlFor={`${id}-description`}>Opis</label><textarea id={`${id}-description`} name="description" rows={4} value={form.description} onChange={event=>{const value=event.currentTarget.value;setForm(previous=>updateValue(previous,"description",value));}}/><TicketFields form={form} setForm={setForm}/><button type="submit">Utwórz ticket</button></form>;}

