export function emptyValues():Values{return {title:"",description:"",priority:"MEDIUM",assignee:null,kind:"TASK",fromCustomer:false,tags:[],estimateHours:"",dueDate:""};}
export function isPriority(value:string):value is Priority{return PRIORITIES.some(priority=>priority===value);}
export function isTag(value:string):value is Tag{return TAGS.some(tag=>tag===value);}
export function parseAssignee(value:string):Person|null|undefined{return value===""?null:PEOPLE.find(person=>person===value);}
export function parseEstimate(raw:string):number|""|null{if(raw.trim()==="")return "";const value=Number(raw);return Number.isFinite(value)?value:null;}
export function validEstimate(value:number|""):boolean{return value===""||(Number.isFinite(value)&&value>=0&&Number.isInteger(value*2));}
export function updateValue<K extends keyof Values>(current:Values,key:K,value:Values[K]):Values{return {...current,[key]:value};}
export function toggleTag(current:Values,tag:Tag):Values{return {...current,tags:current.tags.includes(tag)?current.tags.filter(value=>value!==tag):[...current.tags,tag]};}
export function readSelectedTags(options:ArrayLike<{value:string}>):Tag[]{return [...new Set(Array.from(options,option=>option.value).filter(isTag))];}
export type TicketDraft=Omit<Values,"estimateHours">&{estimateHours:number|null};
export function toDraft(values:Values):TicketDraft{return {...values,title:values.title.trim(),tags:[...values.tags],estimateHours:values.estimateHours===""?null:values.estimateHours};}
